import csv
# The network structure to be measured: dataset_network.csv
# Return an array of 470 networks
def read_network(file_name='dataset_network.csv'):
    with open(file_name, 'r', newline='') as f:
        dims = [row for row in csv.reader(f)]
        del dims[0]
        for dim in dims:
            dim[0] = int(dim[0])
            dim[1] = int(dim[1])
            dim[2] = int(dim[2])
            dim[3] = int(dim[3])
            dim[4] = int(dim[4])
            dim[5] = int(dim[5])
    # print('len(dims)=' + str(len(dims)))
    return dims








